BEGIN;
CREATE TABLE legal_builder.draft_merge_operation(
 id uuid PRIMARY KEY,project_id uuid NOT NULL REFERENCES legal_builder.legal_document_project(id),target_branch_id uuid NOT NULL REFERENCES legal_builder.draft_branch(id),target_workspace_id uuid NOT NULL REFERENCES legal_builder.draft_workspace(id),base_version_id uuid NOT NULL REFERENCES legal_builder.draft_version(id),ours_version_id uuid NOT NULL REFERENCES legal_builder.draft_version(id),theirs_version_id uuid NOT NULL REFERENCES legal_builder.draft_version(id),status_code text NOT NULL,analysis_algorithm_code text NOT NULL,analysis_algorithm_version text NOT NULL,input_checksum_sha256 char(64) NOT NULL,preview_checksum_sha256 char(64) NOT NULL,target_workspace_revision bigint NOT NULL,reason text NOT NULL,authority_basis text NOT NULL,created_at timestamptz NOT NULL,created_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),created_by_membership_id uuid REFERENCES legal_builder.project_membership(id),completed_version_id uuid REFERENCES legal_builder.draft_version(id),completed_at timestamptz,abandoned_at timestamptz,abandoned_reason text,
 CONSTRAINT ck_merge_status CHECK(status_code IN('CONFLICTS_OPEN','READY','COMPLETED','ABANDONED')),CONSTRAINT ck_merge_versions_distinct CHECK(ours_version_id<>theirs_version_id),CONSTRAINT ck_merge_checksums CHECK(input_checksum_sha256~'^[0-9A-Fa-f]{64}$' AND preview_checksum_sha256~'^[0-9A-Fa-f]{64}$'),CONSTRAINT ck_merge_reason CHECK(btrim(reason)<>'' AND btrim(authority_basis)<>''),CONSTRAINT ck_merge_terminal CHECK((status_code='COMPLETED' AND completed_version_id IS NOT NULL AND completed_at IS NOT NULL AND abandoned_at IS NULL) OR (status_code='ABANDONED' AND abandoned_at IS NOT NULL AND btrim(coalesce(abandoned_reason,''))<>'' AND completed_version_id IS NULL) OR (status_code IN('CONFLICTS_OPEN','READY') AND completed_version_id IS NULL AND completed_at IS NULL AND abandoned_at IS NULL))
);
CREATE TABLE legal_builder.draft_merge_conflict(
 id uuid PRIMARY KEY,merge_operation_id uuid NOT NULL REFERENCES legal_builder.draft_merge_operation(id),legal_node_id uuid NOT NULL,conflict_kind_code text NOT NULL,base_state jsonb,ours_state jsonb,theirs_state jsonb,evidence_checksum_sha256 char(64) NOT NULL,created_at timestamptz NOT NULL,UNIQUE(merge_operation_id,legal_node_id),CONSTRAINT ck_merge_conflict_kind CHECK(conflict_kind_code IN('CONTENT','DELETE_MODIFY','ADD_ADD','MOVE_MOVE','REPARENT_DELETE','ORDER_COLLISION','REFERENCE_INTEGRITY','TREE_INVARIANT')),CONSTRAINT ck_merge_conflict_checksum CHECK(evidence_checksum_sha256~'^[0-9A-Fa-f]{64}$')
);
CREATE TABLE legal_builder.draft_merge_conflict_resolution(
 id uuid PRIMARY KEY,conflict_id uuid NOT NULL REFERENCES legal_builder.draft_merge_conflict(id),sequence integer NOT NULL,choice_code text NOT NULL,manual_result jsonb,reason text NOT NULL,authority_basis text NOT NULL,supersedes_resolution_id uuid REFERENCES legal_builder.draft_merge_conflict_resolution(id),decided_at timestamptz NOT NULL,decided_by_user_id uuid NOT NULL REFERENCES legal_builder.user_account(id),decided_by_membership_id uuid REFERENCES legal_builder.project_membership(id),UNIQUE(conflict_id,sequence),CONSTRAINT ck_merge_resolution_sequence CHECK(sequence>0),CONSTRAINT ck_merge_resolution_choice CHECK(choice_code IN('USE_OURS','USE_THEIRS','USE_MANUAL_RESULT')),CONSTRAINT ck_merge_manual_result CHECK((choice_code='USE_MANUAL_RESULT' AND jsonb_typeof(manual_result)='object') OR (choice_code<>'USE_MANUAL_RESULT' AND manual_result IS NULL)),CONSTRAINT ck_merge_resolution_reason CHECK(btrim(reason)<>'' AND btrim(authority_basis)<>''),CONSTRAINT ck_merge_resolution_supersede CHECK((sequence=1 AND supersedes_resolution_id IS NULL) OR (sequence>1 AND supersedes_resolution_id IS NOT NULL))
);
CREATE INDEX ix_merge_operation_project ON legal_builder.draft_merge_operation(project_id,created_at DESC);CREATE INDEX ix_merge_conflict_operation ON legal_builder.draft_merge_conflict(merge_operation_id);CREATE INDEX ix_merge_resolution_conflict ON legal_builder.draft_merge_conflict_resolution(conflict_id,sequence DESC);
CREATE TRIGGER tr_merge_conflict_immutable BEFORE UPDATE OR DELETE ON legal_builder.draft_merge_conflict FOR EACH ROW EXECUTE FUNCTION legal_builder.reject_immutable_change();CREATE TRIGGER tr_merge_resolution_immutable BEFORE UPDATE OR DELETE ON legal_builder.draft_merge_conflict_resolution FOR EACH ROW EXECUTE FUNCTION legal_builder.reject_immutable_change();
COMMIT;
